require_once __DIR__.'/../app/Core/DB.php';require_once __DIR__.'/../app/Services/AnggaranDocumentService.php';$db=DB::getInstance();$ok=static function($v,$m){if(!$v)throw new RuntimeException('FAIL: '.$m);echo "PASS: $m\n";};$u=$db->query('SELECT * FROM user_sesendok_biila WHERE disable=0 AND kd_opd IS NOT NULL AND tahun=2026 ORDER BY id LIMIT 1')->fetch();$dpa=$db->query('SELECT * FROM dpa_neo WHERE kd_wilayah=? AND kd_opd=? AND tahun=? AND is_deleted=0 ORDER BY id LIMIT 1',[$u['kd_wilayah'],$u['kd_opd'],$u['tahun']])->fetch();$s=new AnggaranDocumentService($u);$values=array_fill(1,12,0);$values[1]=(float)$dpa['jumlah']/2;$saved=$s->saveMonthlyPlan('dpa',(int)$dpa['id'],$values);$ok(abs($saved['total']-$values[1])<.01,'rencana penarikan DPA tersimpan per rincian dan bulan');$over=$values;$over[2]=(float)$dpa['jumlah'];try{$s->saveMonthlyPlan('dpa',(int)$dpa['id'],$over);$guard=false;}catch(Throwable $e){$guard=true;}$ok($guard,'total rencana tidak dapat melebihi pagu rincian');$ok(count($s->activeTapd($u['tahun'].'-09-01'))>=5,'TAPD dipilih berdasarkan masa berlaku tanggal cetak');foreach(['dpa','dppa'] as $type){$x=$s->exportRecapExcel($type);$ok(is_file($x)&&filesize($x)>1000,"rekap Excel $type valid");unlink($x);$ok(str_starts_with($s->exportRecapPdf($type),'%PDF'),"rekap PDF $type valid");}$routes=file_get_contents(__DIR__.'/../routes/web.php');foreach(['rencana_bulanan','export_rekap_excel','export_rekap_pdf','tapd/save'] as $f)$ok(str_contains($routes,$f),"route $f tersedia");$js=file_get_contents(__DIR__.'/../public/assets/js/modules/anggaran-document.js');$ok(str_contains($js,'<colgroup>')&&str_contains($js,'fixed table'),'lebar header dan isi memakai colgroup yang sama');echo "PHASE 30 TESTS COMPLETE\n";
